  `de0201054` varchar(50) DEFAULT NULL COMMENT '中文域名',
  `de0201046` varchar(50) DEFAULT NULL COMMENT '英文域名',
  `de0810009` char(8) DEFAULT NULL COMMENT '部门成立日期',
  `de0810010` int(8) DEFAULT NULL COMMENT '部门从业人员数',
