  `de0810044` decimal(8,2) DEFAULT NULL COMMENT '营业面积(m2)',
  `de0810050` decimal(8,2) DEFAULT NULL COMMENT '自有房屋面积(m2)',
  `de0810051` decimal(8,2) DEFAULT NULL COMMENT '租借房屋面积(m2)',
  `status` char(1) DEFAULT NULL COMMENT '状态',
